import numpy as np
def Hdip(x,y,z):
    r2=x*x+y*y+z*z; r=np.sqrt(r2); r5=r2*r2*r; r7=r5*r2
    return np.array([[-3*z/r5+15*z*x*x/r7,15*z*x*y/r7,-3*x/r5+15*z*z*x/r7],
                     [15*z*x*y/r7,-3*z/r5+15*z*y*y/r7,-3*y/r5+15*z*z*y/r7],
                     [-3*x/r5+15*z*z*x/r7,-3*y/r5+15*z*z*y/r7,-9*z/r5+15*z*z*z/r7]])
def basis(th,ph):  # rows = (north, west, up)
    st,ct=np.sin(th),np.cos(th); cp,sp=np.cos(ph),np.sin(ph)
    return np.stack([np.array([-ct*cp,-ct*sp,st]),np.array([sp,-cp,0.]),np.array([st*cp,st*sp,ct])])
# validate: H_loc = L @ H @ L.T ;  tzz (idx2) = up^T H up = V_rr = 6 cos th
for (th,ph) in [(0.37,0.55),(1.0,1.1),(1.57,0.3),(2.2,0.9)]:
    p=np.array([np.sin(th)*np.cos(ph),np.sin(th)*np.sin(ph),np.cos(th)])
    L=basis(th,ph); Hloc=L@Hdip(*p)@L.T
    assert abs(Hloc[2,2]-6*np.cos(th))<1e-9, f"FAIL {Hloc[2,2]} {6*np.cos(th)}"
print("VALIDATED: H_loc = L@H@L.T, tzz=up^T H up=6cos(th).\n")
ten=np.loadtxt('.test/m_ten.txt')
n,nl=34,68; theta=np.arange(n)*np.pi/n
def getT(l,m,ic):
    sel=(ten[:,0]==l)&(ten[:,1]==m)&(ten[:,2]==ic)
    return ten[sel,3:9].reshape(n,nl,6)
T=getT(1,0,1)
names=["txx","tyy","tzz","txy","txz","tyz"]
worst={nm:0 for nm in names}
for i in range(2,n-2):
    th=theta[i]; ph=6*2*np.pi/nl
    p=np.array([np.sin(th)*np.cos(ph),np.sin(th)*np.sin(ph),np.cos(th)])
    L=basis(th,ph); Hloc=L@Hdip(*p)@L.T
    tru=np.array([Hloc[0,0],Hloc[1,1],Hloc[2,2],Hloc[0,1],Hloc[0,2],Hloc[1,2]])
    lib=T[i,6]; sc=np.abs(tru).max()
    for k,nm in enumerate(names):
        if sc>1e-9: worst[nm]=max(worst[nm],abs(lib[k]-tru[k])/sc)
print("Dipole A=1: library tensor vs correct analytic local Hessian (max rel err per component):")
for nm in names: print(f"    {nm}: {worst[nm]:.4e}")
